-	 */
-	public void setComponentsEnabled(String prefix, boolean enabled) {
-		for (Iterator iter = _bindings.values().iterator(); iter.hasNext();) {
-			Binding b = (Binding) iter.next();
-			if (b.getProperty().startsWith(prefix)) {
-				b.setEnabled(enabled);
-			}
-		}
-	}
